-- Frame survivability: the player frames, and the weapons each NPC attacks with.
-- Loaded from Lancer_Compendium_Data_v8.xlsx, the reviewed spreadsheet. After this, the tables are the
-- source of truth, and every later change is a new migration.

-- Frames: the player mechs. Their stats are the same under both rulesets
CREATE TABLE lancer_frames (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    source TEXT NOT NULL,
    role_1 TEXT NOT NULL CHECK (role_1 IN ('Artillery', 'Balanced', 'Controller', 'Defender', 'Striker', 'Support')),
    role_2 TEXT CHECK (role_2 IN ('Artillery', 'Balanced', 'Controller', 'Defender', 'Striker', 'Support')),
    worst_mount TEXT CHECK (worst_mount IN ('Aux/Aux', 'Main', 'Main/Aux', 'Flex', 'Heavy')),
    mid_mount TEXT CHECK (mid_mount IN ('Aux/Aux', 'Main', 'Main/Aux', 'Flex', 'Heavy')),
    best_mount TEXT CHECK (best_mount IN ('Aux/Aux', 'Main', 'Main/Aux', 'Flex', 'Heavy')),
    efficient_core INTEGER NOT NULL CHECK (efficient_core IN (0, 1)),
    size REAL NOT NULL CHECK (size IN (0.5, 1, 2, 3)),
    armor INTEGER NOT NULL,
    hp INTEGER NOT NULL,
    evasion INTEGER NOT NULL,
    e_defense INTEGER NOT NULL,
    heat_cap INTEGER NOT NULL,
    repair_cap INTEGER NOT NULL,
    sensors INTEGER NOT NULL,
    tech_attack INTEGER NOT NULL,
    save_target INTEGER NOT NULL,
    speed INTEGER NOT NULL,
    system_points INTEGER NOT NULL,
    -- Repairs it takes to restore 1 structure: 2 normally, 1 for Everest's Replaceable Parts
    structure_repair_cost INTEGER NOT NULL CHECK (structure_repair_cost IN (1, 2))
) STRICT;

-- Damage types a frame resists (takes half, rounded up) or is immune to (takes none)
CREATE TABLE lancer_frame_damage_traits (
    frame_id INTEGER NOT NULL REFERENCES lancer_frames (id),
    damage_type TEXT NOT NULL CHECK (damage_type IN ('Burn', 'Energy', 'Explosive', 'Kinetic')),
    trait TEXT NOT NULL CHECK (trait IN ('resist', 'immune')),
    PRIMARY KEY (frame_id, damage_type)
) STRICT;

-- An NPC's weapons. The lancer_npcs row it belongs to says which ruleset and tier
CREATE TABLE lancer_npc_weapons (
    id INTEGER PRIMARY KEY,
    npc_id INTEGER NOT NULL REFERENCES lancer_npcs (id),
    slot TEXT NOT NULL CHECK (slot IN ('primary', 'secondary')),
    name TEXT NOT NULL,
    size TEXT CHECK (size IN ('Auxiliary', 'Main', 'Heavy', 'Superheavy')),
    weapon_type TEXT CHECK (weapon_type IN ('Melee', 'CQB', 'Rifle', 'Cannon', 'Launcher', 'Nexus')),
    attack_bonus INTEGER NOT NULL,
    accuracy INTEGER NOT NULL,
    multiattack INTEGER NOT NULL CHECK (multiattack >= 1),
    range_1 TEXT,
    range_2 TEXT,
    effect TEXT,
    on_hit TEXT,
    UNIQUE (npc_id, slot)
) STRICT;

-- A weapon's damage, zero to two rows. Position 1 is the type a Reliable miss deals
CREATE TABLE lancer_weapon_damage (
    weapon_id INTEGER NOT NULL REFERENCES lancer_npc_weapons (id),
    position INTEGER NOT NULL CHECK (position IN (1, 2)),
    amount INTEGER NOT NULL CHECK (amount >= 0),
    damage_type TEXT NOT NULL CHECK (damage_type IN ('Burn', 'Energy', 'Explosive', 'Heat', 'Kinetic', 'Variable')),
    PRIMARY KEY (weapon_id, position)
) STRICT;

-- A weapon's tags, one row each. value holds the number for tags that have one: Reliable 3 is 3
CREATE TABLE lancer_weapon_tags (
    weapon_id INTEGER NOT NULL REFERENCES lancer_npc_weapons (id),
    tag TEXT NOT NULL CHECK (tag IN ('AP', 'Arcing', 'Heat Self', 'Knockback', 'Loading', 'Ordnance', 'Reliable', 'Seeking', 'Smart', 'Thrown')),
    value INTEGER,
    PRIMARY KEY (weapon_id, tag)
) STRICT;



-- npc_id is looked up by ruleset, name and tier, so it doesn't depend on the ids 0004 happened to assign


